#include <iostream>
#include <string>
#include <vector>
using namespace std;

string lessThan20[] = {"","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"};
string tens[] = {"","Ten","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"};
string thousands[] = {"","Thousand","Million","Billion"};

string convert(int n) {
  if (n == 0) return "";
  if (n < 20) return lessThan20[n];
  if (n < 100) return tens[n/10] + (n%10 ? " " + lessThan20[n%10] : "");
  return lessThan20[n/100] + " Hundred" + (n%100 ? " " + convert(n%100) : "");
}

string numberToWords(int num) {
  if (num == 0) return "Zero";
  string result;
  int i = 0;
  while (num) {
    int chunk = num % 1000;
    if (chunk) {
      string chunkWords = convert(chunk);
      string mag = thousands[i];
      result = chunkWords + (mag.empty() ? "" : " " + mag) + (result.empty() ? "" : " " + result);
    }
    num /= 1000;
    i++;
  }
  return result;
}

int main() {
  int n;
  cin >> n;
  cout << numberToWords(n) << endl;
  return 0;
}
